import type { LanguagePreferences, SupportedLanguage } from '../types';

export const LANGUAGE_OPTIONS: Array<{ code: SupportedLanguage; label: string; nativeLabel: string; flagCode: string }> = [
  { code: 'en', label: 'English', nativeLabel: 'English', flagCode: 'gb' },
  { code: 'es', label: 'Spanish', nativeLabel: 'Español', flagCode: 'es' },
  { code: 'pt', label: 'Portuguese', nativeLabel: 'Português', flagCode: 'br' },
  { code: 'fr', label: 'French', nativeLabel: 'Français', flagCode: 'fr' },
  { code: 'de', label: 'German', nativeLabel: 'Deutsch', flagCode: 'de' },
  { code: 'it', label: 'Italian', nativeLabel: 'Italiano', flagCode: 'it' },
  { code: 'ru', label: 'Russian', nativeLabel: 'Русский', flagCode: 'ru' },
  { code: 'sv', label: 'Swedish', nativeLabel: 'Svenska', flagCode: 'se' },
];

export const DEFAULT_LANGUAGE_PREFERENCES: LanguagePreferences = { ui: 'en', game: 'en', ai: 'en' };

export function normalizeLanguagePreferences(value: unknown): LanguagePreferences {
  const allowed = new Set(LANGUAGE_OPTIONS.map(({ code }) => code));
  const source = value && typeof value === 'object' ? value as Partial<LanguagePreferences> : {};
  const pick = (candidate: unknown) => typeof candidate === 'string' && allowed.has(candidate as SupportedLanguage)
    ? candidate as SupportedLanguage : 'en';
  return { ui: pick(source.ui), game: pick(source.game), ai: pick(source.ai) };
}

export function languageLabel(code: SupportedLanguage): string {
  return LANGUAGE_OPTIONS.find((option) => option.code === code)?.nativeLabel || 'English';
}

export function countryDisplayName(code: string, language: SupportedLanguage) {
  try { return new Intl.DisplayNames(language, { type: 'region' }).of(code) || code; } catch { return code; }
}

